10: interface I0024Policy { function isValidSignature(bytes32 digest, bytes calldata sig) external view returns (bytes4); }
11: abstract contract C0024 {
12:   bytes4 internal constant MAGIC = 0x1626ba7e;
13:   I0024Policy public immutable policy;
14:   mapping(bytes32 => bool) public consumed;
15:   constructor(I0024Policy policy_) { policy = policy_; }
16:   function execute(address recipient, uint256 amount, uint256 nonce, bytes calldata signature) external {
17:     bytes32 digest = keccak256(abi.encode(block.chainid, address(this), recipient, amount, nonce));
18:     require(!consumed[digest], "used");
19:     consumed[digest] = true;
20:     require(policy.isValidSignature(digest, signature) == MAGIC, "signature");
21:     _execute(recipient, amount);
22:   }
23:   function _execute(address recipient, uint256 amount) internal virtual;
24: }

